import React, {memo, useCallback, useMemo} from 'react';

import {Loader, getConfig} from '@gravity-ui/uikit';

import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {cnTrackerSelect} from '../TrackerSelect.classname';
import {selectedItemsGroupId} from '../constants';
import {useExpandedGroups} from '../hooks/useExpandedGroups';
import {useSelectedItemsIds} from '../hooks/useSelectedItemsIds';
import {defaultMessages} from '../i18n';
import type {TrackerSelectGroup, TrackerSelectItem, TrackerSelectItemValueBase} from '../types';

import {SelectGroup} from './SelectGroup';

export type ItemsListProps<Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase> =
    {
        groups?: TrackerSelectGroup<Value>[];
        selectedItems?: TrackerSelectItem<Value>[];
        disabledItemsIds?: string[];
        onItemClick?: (item: TrackerSelectItem<Value>) => void;
        onItemPin?: (id: string) => void;
        onItemUnpin?: (id: string) => void;
        activeItemId?: string;
        className?: string;
        isLoading?: boolean;
        showSelectedGroup?: boolean;
        chosenGroupTitle?: string;
        isGroupExpandedByDefault?: (group: TrackerSelectGroup<Value>) => boolean;
        resetExpandedStateOnGroupsChange?: boolean;
        hideIfAllSelected?: boolean;
        showSelectedMeta?: boolean;
    } & Pick<
        Parameters<typeof SelectGroup>[0],
        | 'renderItem'
        | 'renderInfo'
        | 'showArrowOnUnselectedItems'
        | 'hideCheckbox'
        | 'singleSelect'
        | 'showMeta'
        | 'itemActions'
        | 'pinnable'
        | 'disableDefaultItemRender'
        | 'itemClassName'
    >;

const ItemsListWrapped = <Value extends TrackerSelectItemValueBase>({
    groups,
    selectedItems,
    disabledItemsIds,
    onItemClick,
    onItemPin,
    onItemUnpin,
    activeItemId,
    renderItem,
    renderInfo,
    showArrowOnUnselectedItems,
    hideCheckbox,
    singleSelect,
    showMeta,
    itemActions,
    pinnable,
    disableDefaultItemRender,
    itemClassName,
    className,
    isLoading = false,
    showSelectedGroup,
    chosenGroupTitle,
    isGroupExpandedByDefault,
    resetExpandedStateOnGroupsChange,
    hideIfAllSelected,
    showSelectedMeta,
}: ItemsListProps<Value>) => {
    const selectedItemsIds = useSelectedItemsIds(selectedItems);
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);

    const {expandedGroups, handleExpandChange} = useExpandedGroups(
        groups,
        resetExpandedStateOnGroupsChange,
        isGroupExpandedByDefault,
    );

    const toggleItem = useCallback(
        (item: TrackerSelectItem<Value>) => {
            onItemClick?.(item);
        },
        [onItemClick],
    );

    const itemsMap: Record<string, TrackerSelectItem<Value>> = useMemo(
        () => groups?.reduce((target, group) => Object.assign(target, group.items), {}) ?? {},
        [groups],
    );

    const selectedItemGroups = useMemo(() => {
        if (!showSelectedGroup || !selectedItems?.length) {
            return [];
        }

        const buildSelectedGroupItems = (items: TrackerSelectItem<Value>[]) =>
            items.reduce<Record<string, TrackerSelectItem<Value>>>((target, itemData, index) => {
                let item: TrackerSelectItem<Value> | undefined;

                if (itemsMap[itemData.id]) {
                    item = {
                        ...itemsMap[itemData.id],
                        ...itemData,
                    };
                } else {
                    item = {...itemData};
                }

                const res = {...target};

                if (item) {
                    res[index] = item;
                }

                return res;
            }, {});

        return [
            {
                id: selectedItemsGroupId,
                name: singleSelect ? undefined : chosenGroupTitle || t('selectedTitle'),
                collapsible: singleSelect ? (false as const) : true,
                isGroupExpandedByDefault: true,
                items: buildSelectedGroupItems(selectedItems),
            },
        ];
    }, [showSelectedGroup, selectedItems, singleSelect, chosenGroupTitle, itemsMap, t]);

    const {regularGroups, topmostGroups} = useMemo(() => {
        if (!groups) {
            return {regularGroups: [], topmostGroups: []};
        }

        const regular: TrackerSelectGroup<Value>[] = [];
        const topmost: TrackerSelectGroup<Value>[] = [];

        for (const group of groups) {
            if (group.topmost) {
                const groupItems = selectedItemsIds
                    ? Object.entries(group.items).reduce((res, [key, item]) => {
                          if (!selectedItemsIds.includes(item.id)) {
                              return {...res, [key]: item};
                          }
                          return res;
                      }, {})
                    : group.items;
                if (Object.keys(groupItems).length > 0) {
                    topmost.push({...group, items: groupItems});
                }
            } else if (selectedItemsIds?.length && showSelectedGroup) {
                const filteredItems: Record<string, TrackerSelectItem<Value>> = {};
                for (const [id, item] of Object.entries(group.items)) {
                    if (!selectedItemsIds.includes(id)) {
                        filteredItems[id] = item;
                    }
                }
                regular.push({...group, items: filteredItems});
            } else {
                regular.push(group);
            }
        }

        return {regularGroups: regular, topmostGroups: topmost};
    }, [groups, selectedItemsIds, showSelectedGroup]);

    const allItemsSelected = useMemo(() => {
        const allItemsCount = groups?.reduce(
            (sum, group) => sum + Object.keys(group.items).length,
            0,
        );
        return selectedItemsIds?.length === allItemsCount;
    }, [groups, selectedItemsIds?.length]);

    if (isLoading) {
        return <Loader className={cnTrackerSelect('loader')} size="m" />;
    }

    const showSelectedItems = hideIfAllSelected ? !allItemsSelected : true;

    const groupsTransform = (group: (typeof regularGroups)[number]) => (
        <SelectGroup
            key={group.id}
            group={group}
            items={Object.values(group.items ?? {})}
            selectedItemsIds={selectedItemsIds}
            disabledItemsIds={disabledItemsIds}
            onItemClick={toggleItem}
            onItemPin={onItemPin}
            onItemUnpin={onItemUnpin}
            activeItemId={activeItemId}
            expanded={expandedGroups[group.id]}
            onExpandChange={handleExpandChange}
            renderItem={renderItem}
            renderInfo={renderInfo}
            showArrowOnUnselectedItems={showArrowOnUnselectedItems}
            hideCheckbox={hideCheckbox}
            singleSelect={singleSelect}
            showMeta={showMeta}
            itemActions={itemActions}
            pinnable={pinnable}
            disableDefaultItemRender={disableDefaultItemRender}
            itemClassName={itemClassName}
            groupId={group.id}
            collapsible={group.collapsible}
            withHeading={Boolean(group.name)}
        />
    );

    return (
        <div className={cnTrackerSelect('list', className)}>
            {topmostGroups.map(groupsTransform)}

            {showSelectedItems &&
                selectedItemGroups.map((selectedItemGroup) => (
                    <SelectGroup
                        key={selectedItemGroup.id}
                        group={selectedItemGroup}
                        items={Object.values(selectedItemGroup.items ?? {})}
                        selectedItemsIds={selectedItemsIds}
                        disabledItemsIds={disabledItemsIds}
                        onItemClick={toggleItem}
                        onItemPin={onItemPin}
                        onItemUnpin={onItemUnpin}
                        activeItemId={activeItemId}
                        expanded={expandedGroups[selectedItemGroup.id]}
                        onExpandChange={handleExpandChange}
                        renderItem={renderItem}
                        renderInfo={renderInfo}
                        showArrowOnUnselectedItems={showArrowOnUnselectedItems}
                        hideCheckbox={hideCheckbox}
                        singleSelect={singleSelect}
                        showMeta={showSelectedMeta}
                        itemActions={itemActions}
                        pinnable={pinnable}
                        disableDefaultItemRender={disableDefaultItemRender}
                        itemClassName={itemClassName}
                        groupId={selectedItemGroup.id}
                        collapsible={selectedItemGroup.collapsible}
                        withHeading={Boolean(selectedItemGroup.name)}
                    />
                ))}

            {regularGroups.map(groupsTransform)}
        </div>
    );
};

export const ItemsList = memo(ItemsListWrapped) as typeof ItemsListWrapped;
